package dev.oqthara.runtime;

/**
 * Arithmetic helpers used by generated bytecode. The verifier-friendly route is to call
 * these instead of emitting type-dispatch inline: Oqthara numbers are dynamically typed
 * (long or double), and reproducing `Values.add` semantics with JVM instructions would
 * require branches and stack maps.
 *
 * <p>Each method takes and returns {@code Object}, boxes its arguments only when needed, and
 * mirrors the interpreter exactly because it delegates to {@link Values}.
 */
public final class Arithmetic {
    private Arithmetic() {
    }

    public static Object add(Object a, Object b) {
        return Values.add(a, b, Errors.current());
    }

    public static Object subtract(Object a, Object b) {
        return Values.subtract(a, b, Errors.current());
    }

    public static Object multiply(Object a, Object b) {
        return Values.multiply(a, b, Errors.current());
    }

    public static Object divide(Object a, Object b) {
        return Values.divide(a, b, Errors.current());
    }

    public static Object modulo(Object a, Object b) {
        return Values.modulo(a, b, Errors.current());
    }

    public static Object power(Object a, Object b) {
        return Values.power(a, b, Errors.current());
    }

    public static Object negate(Object a) {
        return Values.negate(a, Errors.current());
    }

    /**
     * Prints one value followed by a newline, using the same rendering as the interpreter and
     * UTF-8 regardless of the platform default charset.
     */
    public static void print(Object value) {
        String text = Values.display(value);
        String newline = System.lineSeparator();
        chargeWritten(text.getBytes(java.nio.charset.StandardCharsets.UTF_8).length
                + newline.getBytes(java.nio.charset.StandardCharsets.UTF_8).length);
        out().print(text);
        out().print(newline);
        out().flush();
    }

    /** Truthiness, exactly as the interpreter decides it. */
    public static boolean truthy(Object value) {
        return Values.truthy(value);
    }

    public static Object not(Object value) {
        return Values.not(value);
    }

    /** Renders a value as text, exactly as interpolation does in the interpreter. */
    public static Object text(Object value) {
        return Values.display(value);
    }

    /** Converts any value to an Oqthara boolean, as the interpreter's truthiness does. */
    public static Object toBoolean(Object value) {
        return Values.truthy(value);
    }

    public static Object less(Object a, Object b) {
        return Values.compare(a, b, Errors.current()) < 0;
    }

    public static Object lessOrEqual(Object a, Object b) {
        return Values.compare(a, b, Errors.current()) <= 0;
    }

    public static Object greater(Object a, Object b) {
        return Values.compare(a, b, Errors.current()) > 0;
    }

    public static Object greaterOrEqual(Object a, Object b) {
        return Values.compare(a, b, Errors.current()) >= 0;
    }

    public static Object equal(Object a, Object b) {
        return Values.equal(a, b);
    }

    public static Object notEqual(Object a, Object b) {
        return !Values.equal(a, b);
    }

    /** Prints a value without a newline. */
    public static void write(Object value) {
        String text = Values.display(value);
        chargeWritten(text.getBytes(java.nio.charset.StandardCharsets.UTF_8).length);
        out().print(text);
        out().flush();
    }

    /**
     * The most one compiled program may write, matching {@code MAX_TEXT_BYTES} in the stdlib.
     *
     * <p>Compiled code has no step counter to bill — the program is bytecode, so there is no
     * interpreter loop to charge. Output is the one host transfer a jar performs, so it keeps
     * its own ceiling rather than letting a built program print without bound. The charge
     * happens before the bytes are written, so a refused print emits nothing.
     */
    private static void chargeWritten(long bytes) {
        OutputBudget.charge(bytes);
    }

    private static java.io.PrintStream out() {
        if (UTF8_OUT == null) {
            UTF8_OUT = new java.io.PrintStream(System.out, true, java.nio.charset.StandardCharsets.UTF_8);
        }
        return UTF8_OUT;
    }

    private static volatile java.io.PrintStream UTF8_OUT;
}
